-- =====================================================================
-- POPULAÇÃO COMPLETA DE TRADUÇÕES HARMONIZADAS CLP (ECHA ANEXO VI)
-- Projetado especificamente para o motor de importação de matérias-primas .xls
-- =====================================================================

-- ---------------------------------------------------------------------
-- [H224] Líquido e vapor extremamente inflamáveis
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H224', 'PT', 'FirstAid', 'Retirar imediatamente a roupa contaminada. Lavar a pele com água ou tomar um duche. Em caso de inalação, retirar a pessoa para o ar livre.'),
('H224', 'PT', 'Firefighting', 'Utilizar pó químico, espuma resistente ao álcool ou CO2. Arrefecer os contentores com água pulverizada mantendo a distância de segurança.'),
('H224', 'PT', 'AccidentalRelease', 'Eliminar todas as fontes de ignição. Usar apenas ferramentas antichoque. Conter e recolher o derrame com absorventes não combustíveis.'),
('H224', 'PT', 'HandlingStorage', 'Manter afastado do calor, faíscas, chamas abertas e superfícies quentes. Armazenar em local fresco e extremamente bem ventilado.'),
('H224', 'PT', 'ExposureControl', 'Usar luvas de borracha nitrílica ou butílica espessas, óculos estanques e máscara com filtro A2 contra vapores orgânicos de baixo ponto de ebulição.'),
('H224', 'PT', 'Disposal', 'Eliminar como resíduo altamente inflamável e perigoso através de operador licenciado (Código EWC: 08 01 11*).'),
('H224', 'EN', 'FirstAid', 'Take off immediately all contaminated clothing. Rinse skin with water or shower. If inhaled, remove person to fresh air.'),
('H224', 'EN', 'Firefighting', 'Use dry powder, alcohol-resistant foam, or CO2. Cool containers with water spray while maintaining safe distance.'),
('H224', 'EN', 'AccidentalRelease', 'Eliminate all ignition sources. Use non-sparking tools. Contain and collect spillage with non-combustible absorbents.'),
('H224', 'EN', 'HandlingStorage', 'Keep away from heat, sparks, open flames, and hot surfaces. Store in a cool and extremely well-ventilated place.'),
('H224', 'EN', 'ExposureControl', 'Wear thick nitrile or butyl rubber gloves, airtight goggles, and organic vapor mask (Filter type A2) for low-boiling solvents.'),
('H224', 'EN', 'Disposal', 'Dispose of as highly flammable hazardous waste via an authorized contractor (EWC Code: 08 01 11*).');

-- ---------------------------------------------------------------------
-- [H225] Líquido e vapor facilmente inflamáveis (Acetona, Etanol, etc.)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H225', 'PT', 'FirstAid', 'Retirar a pessoa para o ar livre. Lavar a pele com água abundante. Em caso de contacto com os olhos, enxaguar cuidadosamente.'),
('H225', 'PT', 'Firefighting', 'Extinguir com pó químico, CO2 ou espuma resistente ao álcool. NÃO usar jato de água direto.'),
('H225', 'PT', 'AccidentalRelease', 'Afastar fontes de ignição. Evitar acumulação de cargas eletrostáticas. Absorver com terra, areia ou absorvente inerte.'),
('H225', 'PT', 'HandlingStorage', 'Proibir chamas, faíscas ou fontes de calor durante o manuseamento. Ligar recipientes à terra durante transferências.'),
('H225', 'PT', 'ExposureControl', 'Garantir ventilação geral e local adequada. Luvas de proteção química e máscara com filtro tipo A contra solventes.'),
('H225', 'PT', 'Disposal', 'Incineração num centro de tratamento autorizado para resíduos inflamáveis.'),
('H225', 'EN', 'FirstAid', 'Remove person to fresh air. Wash skin with plenty of water. In case of eye contact, rinse cautiously.'),
('H225', 'EN', 'Firefighting', 'Extinguish with dry chemical, CO2, or alcohol-resistant foam. DO NOT use a solid water stream.'),
('H225', 'EN', 'AccidentalRelease', 'Remove all ignition sources. Prevent electrostatic discharge. Absorb with earth, sand, or inert binder.'),
('H225', 'EN', 'HandlingStorage', 'Prohibit flames, sparks, or heat during handling. Bond and ground containers during transfers.'),
('H225', 'EN', 'ExposureControl', 'Ensure adequate general and local ventilation. Wear chemical gloves and organic vapor mask (Filter type A).'),
('H225', 'EN', 'Disposal', 'Incineration at an authorized facility for flammable solvent waste.');

-- ---------------------------------------------------------------------
-- [H226] Líquido e vapor inflamáveis (Xileno, Acetato de Butilo, etc.)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H226', 'PT', 'FirstAid', 'Remover a roupa contaminada. Lavar a pele afetada com água e sabão neutro. Se inalado, repousar ao ar livre.'),
('H226', 'PT', 'Firefighting', 'Utilizar espuma química resistente ao álcool, pó extintor seco ou névoa de água para extinção.'),
('H226', 'PT', 'AccidentalRelease', 'Eliminar potenciais focos de ignição. Evitar a inalação de vapores. Conter o líquido com barreiras físicas absorventes.'),
('H226', 'PT', 'HandlingStorage', 'Utilizar apenas em ferramentas antideflagrantes. Proteger contra a eletricidade estática. Armazenar longe de agentes oxidantes.'),
('H226', 'PT', 'ExposureControl', 'Instalar ventilação exaustiva eficaz no local de aplicação. Luvas nitrílicas resistentes a solventes e óculos de proteção.'),
('H226', 'PT', 'Disposal', 'Enviar para reciclagem de solventes ou eliminação em estação licenciada para resíduos industriais perigosos (EWC: 08 01 11*).'),
('H226', 'EN', 'FirstAid', 'Remove contaminated clothing. Wash affected skin with mild soap and water. If inhaled, rest in fresh air.'),
('H226', 'EN', 'Firefighting', 'Use alcohol-resistant chemical foam, dry chemical powder, or water mist for extinguishing.'),
('H226', 'EN', 'AccidentalRelease', 'Eliminate potential ignition sources. Avoid breathing vapors. Contain liquid with absorbent barriers.'),
('H226', 'EN', 'HandlingStorage', 'Use only non-sparking tools. Protect against static discharge. Store away from oxidizing agents.'),
('H226', 'EN', 'ExposureControl', 'Install effective exhaust ventilation at the workplace. Solvent-resistant nitrile gloves and safety goggles.'),
('H226', 'EN', 'Disposal', 'Send for solvent recycling or disposal at a licensed facility for dangerous industrial waste (EWC: 08 01 11*).');

-- ---------------------------------------------------------------------
-- [H302] Nocivo por ingestão
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H302', 'PT', 'FirstAid', 'Enxaguar a boca com água. NÃO provocar o vómito sem indicação médica. Contactar o Centro de Informação Antivenenos (CIAV).'),
('H302', 'PT', 'HandlingStorage', 'Não comer, beber ou fumar durante a utilização deste produto. Lavar as mãos cuidadosamente após manuseamento.'),
('H302', 'PT', 'ExposureControl', 'Não necessita de proteção específica além de boas práticas de higiene industrial e óculos de proteção padrão.'),
('H302', 'PT', 'Disposal', 'Tratar como resíduo químico perigoso. Entregar num ponto de recolha autorizado.'),
('H302', 'EN', 'FirstAid', 'Rinse mouth with water. DO NOT induce vomiting unless directed by medical personnel. Contact the local poison center.'),
('H302', 'EN', 'HandlingStorage', 'Do not eat, drink, or smoke when using this product. Wash hands thoroughly after handling.'),
('H302', 'EN', 'ExposureControl', 'No specific protection required beyond good industrial hygiene practices and standard safety goggles.'),
('H302', 'EN', 'Disposal', 'Treat as hazardous chemical waste. Deliver to an authorized collection point.');

-- ---------------------------------------------------------------------
-- [H304] Pode ser mortal por ingestão e penetração nas vias respiratórias
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H304', 'PT', 'FirstAid', 'NÃO provocar o vómito devido ao risco gravíssimo de aspiração pulmonar. Chamar imediatamente o CIAV ou assistência médica.'),
('H304', 'PT', 'HandlingStorage', 'Armazenar fechado à chave numa embalagem hermética. Manter fora do alcance de crianças.'),
('H304', 'PT', 'ExposureControl', 'Evitar a libertação de aerossóis. Utilizar em sistemas confinados ou com forte aspiração local.'),
('H304', 'PT', 'Disposal', 'Recipiente e resíduo devem ser entregues obrigatoriamente a um gestor autorizado de resíduos industriais tóxicos.'),
('H304', 'EN', 'FirstAid', 'DO NOT induce vomiting due to critical risk of pulmonary aspiration. Immediately call a poison control center or doctor.'),
('H304', 'EN', 'HandlingStorage', 'Store locked up in a tightly closed hermetic container. Keep out of reach of children.'),
('H304', 'EN', 'ExposureControl', 'Avoid release of aerosols. Use in closed systems or with strong local exhaust ventilation.'),
('H304', 'EN', 'Disposal', 'Container and waste must be strictly disposed of through an authorized hazardous industrial waste manager.');

-- ---------------------------------------------------------------------
-- [H312] Nocivo em contacto com a pele
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H312', 'PT', 'FirstAid', 'Lavar abundantemente a pele com água e sabão durante pelo menos 15 minutos. Retirar o vestuário contaminado imediatamente.'),
('H312', 'PT', 'ExposureControl', 'Obrigatório o uso de luvas resistentes a químicos (Butyl, Viton ou Nitrilo espesso) e vestuário de proteção impermeável.'),
('H312', 'PT', 'Disposal', 'Incineração controlada em local licenciado de acordo com a diretiva de resíduos perigosos.'),
('H312', 'EN', 'FirstAid', 'Wash skin thoroughly with plenty of soap and water for at least 15 minutes. Take off contaminated clothing immediately.'),
('H312', 'EN', 'ExposureControl', 'Mandatory use of chemical-resistant gloves (Butyl, Viton, or thick Nitrile) and impervious protective clothing.'),
('H312', 'EN', 'Disposal', 'Controlled incineration at a licensed facility in accordance with hazardous waste directives.');

-- ---------------------------------------------------------------------
-- [H314] Provoca queimaduras na pele e lesões oculares graves
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H314', 'PT', 'FirstAid', 'Lavar imediatamente com água abundante durante 15 minutos. Retirar lentes de contacto. Chamar assistência médica urgente.'),
('H314', 'PT', 'Firefighting', 'Utilizar pó químico, CO2 ou névoa de água. Os gases de combustão podem conter fumos altamente corrosivos.'),
('H314', 'PT', 'AccidentalRelease', 'Usar EPI químico completo. Conter o derrame com absorvente inerte e neutralizar o resíduo sob supervisão.'),
('H314', 'PT', 'HandlingStorage', 'Armazenar apenas em recipientes resistentes a agentes corrosivos (plásticos de alta densidade). Manter fechado.'),
('H314', 'PT', 'ExposureControl', 'Usar luvas químicas de cano longo, viseira facial protetora e fato de proteção química de alta especificação.'),
('H314', 'PT', 'Disposal', 'Tratar o líquido e embalagens como resíduos de alta toxicidade corrosiva. Não libertar nos sistemas de esgoto públicos.'),
('H314', 'EN', 'FirstAid', 'Immediately flush with plenty of water for 15 minutes. Remove contact lenses. Seek urgent medical assistance.'),
('H314', 'EN', 'Firefighting', 'Use dry chemical, CO2, or water mist. Combustion gases can contain highly corrosive fumes.'),
('H314', 'EN', 'AccidentalRelease', 'Wear full chemical PPE. Contain spill with inert absorbent and neutralize residue under supervision.'),
('H314', 'EN', 'HandlingStorage', 'Store only in corrosion-resistant containers (high-density plastics). Keep tightly closed.'),
('H314', 'EN', 'ExposureControl', 'Wear chemical gauntlet gloves, protective face shield, and high-specification chemical suit.'),
('H314', 'EN', 'Disposal', 'Treat liquid and packaging as highly corrosive hazardous waste. Do not release into public sewer systems.');

-- ---------------------------------------------------------------------
-- [H315] Provoca irritação cutânea
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H315', 'PT', 'FirstAid', 'Lavar a pele afetada com sabão neutro e bastante água. Se persistir a irritação cutânea, procurar aconselhamento médico.'),
('H315', 'PT', 'ExposureControl', 'Usar luvas de proteção em nitrilo (norma EN 374). Evitar o contacto repetido ou prolongado.'),
('H315', 'EN', 'FirstAid', 'Wash affected skin with mild soap and plenty of water. If skin irritation persists, seek medical advice.'),
('H315', 'EN', 'ExposureControl', 'Wear nitrile protective gloves (EN 374). Avoid repeated or prolonged skin contact.');

-- ---------------------------------------------------------------------
-- [H317] Pode provocar uma reação alérgica cutânea (Alergias a Resinas Epóxi)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H317', 'PT', 'FirstAid', 'Lavar abundantemente com água e sabão. Em caso de erupção ou irritação cutânea, procurar assistência médica imediata.'),
('H317', 'PT', 'HandlingStorage', 'Pessoas sensibilizadas não devem manusear este produto. Evitar o contacto com o vestuário e ferramentas de trabalho.'),
('H317', 'PT', 'ExposureControl', 'Uso rigoroso de luvas impermeáveis de proteção química. Higiene das mãos antes de comer, beber ou usar sanitários.'),
('H317', 'PT', 'Disposal', 'Eliminar as embalagens vazias que contêm vestígios do produto como resíduo perigoso, sujeitas a incineração.'),
('H317', 'EN', 'FirstAid', 'Wash with plenty of soap and water. If skin irritation or rash occurs, seek immediate medical assistance.'),
('H317', 'EN', 'HandlingStorage', 'Sensitized persons must not handle this product. Avoid contact with clothing and work tools.'),
('H317', 'EN', 'ExposureControl', 'Strict use of impermeable chemical-resistant gloves. Wash hands before eating, drinking, or using sanitation.'),
('H317', 'EN', 'Disposal', 'Dispose of empty packaging containing product residues as hazardous waste, subject to incineration.');

-- ---------------------------------------------------------------------
-- [H318] Provoca lesões oculares graves
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H318', 'PT', 'FirstAid', 'Lavar os olhos imediatamente com água corrente abundante durante vários minutos, mantendo as pálpebras abertas. Chamar médico especialista.'),
('H318', 'PT', 'ExposureControl', 'Obrigatório o uso de óculos de segurança estanques ou máscara de proteção facial integral.'),
('H318', 'EN', 'FirstAid', 'Rinse eyes immediately with running water for several minutes, holding eyelids open. Consult an eye specialist.'),
('H318', 'EN', 'ExposureControl', 'Mandatory use of chemical safety goggles or a complete protective face shield.');

-- ---------------------------------------------------------------------
-- [H319] Provoca irritação ocular grave
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H319', 'PT', 'FirstAid', 'Enxaguar cuidadosamente com água durante vários minutos. Se a irritação persistir, obter assistência médica.'),
('H319', 'PT', 'ExposureControl', 'Usar óculos de segurança com proteção lateral certificada (norma EN 166).'),
('H319', 'EN', 'FirstAid', 'Rinse cautiously with water for several minutes. If eye irritation persists, get medical attention.'),
('H319', 'EN', 'ExposureControl', 'Wear safety glasses with certified side shields (standard EN 166).');

-- ---------------------------------------------------------------------
-- [H330] Fatal por inalação (Substâncias de Extrema Toxicidade)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H330', 'PT', 'FirstAid', 'Levar imediatamente a vítima para uma zona de ar livre e mantê-la em repouso completo. Administrar oxigénio se necessário. Chamar emergência médica médica.'),
('H330', 'PT', 'AccidentalRelease', 'Evacuar a área de imediato. Equipas de resgate devem usar obrigatoriamente aparelho respiratório autónomo (ARA). Conter gás/fumos.'),
('H330', 'PT', 'HandlingStorage', 'Utilizar apenas em capelas de exaustão química perfeitamente calibradas ou sistemas de circuito fechado.'),
('H330', 'PT', 'ExposureControl', 'Obrigatório o uso de máscara com fornecimento autónomo de ar ou sistema de pressão positiva.'),
('H330', 'PT', 'Disposal', 'Incineração exclusiva em instalações industriais licenciadas para resíduos de toxicidade extrema.'),
('H330', 'EN', 'FirstAid', 'Remove victim to fresh air immediately and keep at complete rest. Administer oxygen if needed. Call medical emergency.'),
('H330', 'EN', 'AccidentalRelease', 'Evacuate the area immediately. Rescue teams must wear self-contained breathing apparatus (SCBA). Contain gas/fumes.'),
('H330', 'EN', 'HandlingStorage', 'Use only in calibrated chemical fume hoods or closed-loop containment systems.'),
('H330', 'EN', 'ExposureControl', 'Mandatory use of self-contained breathing apparatus or positive pressure air-supplied systems.'),
('H330', 'EN', 'Disposal', 'Exclusive incineration at industrial facilities licensed for extremely toxic chemical waste.');

-- ---------------------------------------------------------------------
-- [H332] Nocivo por inalação (Poliisocianatos, Agentes de Cura, etc.)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H332', 'PT', 'FirstAid', 'Retirar a pessoa para o ar livre e mantê-la em posição confortável. Se apresentar dificuldades respiratórias, chamar o médico.'),
('H332', 'PT', 'ExposureControl', 'Garantir boa ventilação local. Usar máscara com filtros combinados contra gases e aerossóis (Filtro A2P3).'),
('H332', 'EN', 'FirstAid', 'Remove person to fresh air and keep comfortable for breathing. If breathing difficulties occur, call a physician.'),
('H332', 'EN', 'ExposureControl', 'Ensure good local exhaust. Wear respiratory mask with combined filters for gases and aerosols (Filter type A2P3).');

-- ---------------------------------------------------------------------
-- [H335] Pode provocar irritação das vias respiratórias
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H335', 'PT', 'FirstAid', 'Levar a pessoa afetada para o ar fresco. Obter assistência médica em caso de persistência dos sintomas de tosse ou falta de ar.'),
('H335', 'PT', 'ExposureControl', 'Em caso de ventilação insuficiente, usar máscara respiratória adequada dotada de filtro para partículas e vapores.'),
('H335', 'EN', 'FirstAid', 'Remove affected person to fresh air. Get medical attention if coughing or shortness of breath symptoms persist.'),
('H335', 'EN', 'ExposureControl', 'In case of inadequate ventilation, wear appropriate respiratory mask with vapor and particulate filters.');

-- ---------------------------------------------------------------------
-- [H336] Pode provocar sonolência ou vertigens (Efeito Narcótico dos Solventes)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H336', 'PT', 'FirstAid', 'Retirar a pessoa para o ar fresco. Se os sintomas de tontura ou desmaio persistirem, colocar em posição de segurança e chamar ajuda médica.'),
('H336', 'PT', 'ExposureControl', 'Garantir forte exaustão local na zona de aplicação. Equipas expostas devem usar máscaras para vapores orgânicos (Filtro A).'),
('H336', 'EN', 'FirstAid', 'Remove affected person to fresh air. If dizziness or fainting persists, place in recovery position and seek medical help.'),
('H336', 'EN', 'ExposureControl', 'Ensure strong local extraction at the application area. Exposed teams must wear organic vapor respirators (Filter type A).');

-- ---------------------------------------------------------------------
-- [H350] Pode provocar cancro (Compostos de Crómio, Pigmentos Pesados, etc.)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H350', 'PT', 'FirstAid', 'Em caso de exposição ou suspeita de exposição: consulte um médico. Mostrar a embalagem e a ficha de dados de segurança.'),
('H350', 'PT', 'HandlingStorage', 'Pedir instruções especiais antes da utilização. Não manusear o produto antes de ter lido e compreendido todas as precauções de segurança.'),
('H350', 'PT', 'ExposureControl', 'Controlo de exposição extremamente rígido. Uso obrigatório de fato de proteção completo de Tyvek, luvas de barreira química e máscara facial com filtro P3.'),
('H350', 'PT', 'Disposal', 'Eliminação obrigatória em instalação industrial licenciada para eliminação de resíduos cancerígenos através de incineração sob alta temperatura.'),
('H350', 'EN', 'FirstAid', 'IF exposed or concerned: Get medical advice/attention. Show the container label and safety data sheet.'),
('H350', 'EN', 'HandlingStorage', 'Obtain special instructions before use. Do not handle until all safety precautions have been read and understood.'),
('H350', 'EN', 'ExposureControl', 'Extremely strict exposure controls. Mandatory use of full Tyvek protective suit, chemical barrier gloves, and full face mask with P3 filters.'),
('H350', 'EN', 'Disposal', 'Mandatory disposal at an industrial facility authorized for carcinogenic waste destruction through high-temperature incineration.');

-- ---------------------------------------------------------------------
-- [H351] Suspeito de provocar cancro (Ex: Dióxido de Titânio em pó)
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H351', 'PT', 'FirstAid', 'Em caso de exposição ou dúvida, consultar imediatamente o médico.'),
('H351', 'PT', 'HandlingStorage', 'Utilizar o equipamento de proteção individual recomendado. Armazenar em local seguro afastado de zonas de lazer.'),
('H351', 'PT', 'ExposureControl', 'Evitar a inalação de poeiras. Utilizar máscara com filtro para poeiras tóxicas ou aerossóis (Filtro P2 ou P3) durante a mistura.'),
('H351', 'EN', 'FirstAid', 'In case of exposure or concern, seek immediate medical advice.'),
('H351', 'EN', 'HandlingStorage', 'Use recommended personal protective equipment. Store in a secure place away from general access areas.'),
('H351', 'EN', 'ExposureControl', 'Avoid inhalation of dusts. Wear dust masks with toxic particle filters (Filter type P2 or P3) during mixing operations.');

-- ---------------------------------------------------------------------
-- [H360] Pode afetar a fertilidade ou o nascituro
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H360', 'PT', 'FirstAid', 'IF exposto ou com suspeita de exposição: consulte um médico imediatamente.'),
('H360', 'PT', 'HandlingStorage', 'Não manusear sem compreender todas as precauções de segurança. Evitar qualquer exposição de mulheres grávidas ou em período de amamentação.'),
('H360', 'PT', 'ExposureControl', 'Instalar sistemas estanques fechados. Uso de EPI completo contra riscos químicos biológicos.'),
('H360', 'EN', 'FirstAid', 'IF exposed or concerned: Get immediate medical advice/attention.'),
('H360', 'EN', 'HandlingStorage', 'Do not handle until all safety precautions have been read and understood. Avoid any exposure during pregnancy or breastfeeding.'),
('H360', 'EN', 'ExposureControl', 'Install sealed closed-loop systems. Wear complete PPE for chemical and biological risks.');

-- ---------------------------------------------------------------------
-- [H400] Muito tóxico para os organismos aquáticos
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H400', 'PT', 'Firefighting', 'Conter a água usada para combater o fogo. Impedir o escoamento para rios, esgotos ou linhas de drenagem pluvial.'),
('H400', 'PT', 'AccidentalRelease', 'Instalar barreiras físicas absorventes de contenção rápida. Não enxaguar a área afetada com água corrente para limpar.'),
('H400', 'PT', 'Disposal', 'Eliminar como resíduo poluente aquático de alta perigosidade através de um operador de gestão licenciado.'),
('H400', 'EN', 'Firefighting', 'Contain water used for firefighting. Prevent runoff into rivers, sewers, or storm drainage lines.'),
('H400', 'EN', 'AccidentalRelease', 'Deploy physical absorbent containment barriers rapidly. Do not rinse the spill area with running water for cleaning.'),
('H400', 'EN', 'Disposal', 'Dispose of as highly hazardous aquatic pollutant waste through a licensed management operator.');

-- ---------------------------------------------------------------------
-- [H410] Muito tóxico para os organismos aquáticos com efeitos duradouros
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H410', 'PT', 'Firefighting', 'Conter de forma absoluta a água de extinção. A descarga nos sistemas de saneamento é estritamente proibida.'),
('H410', 'PT', 'AccidentalRelease', 'Prevenir a propagação de derrames. Recolher imediatamente com materiais absorventes secos.'),
('H410', 'PT', 'Disposal', 'Tratar como resíduo altamente ecotóxico. Reciclagem ou destruição segundo o código EWC aplicável.'),
('H410', 'EN', 'Firefighting', 'Absolutely contain all firefighting water. Discharge into the sewage system is strictly prohibited.'),
('H410', 'EN', 'AccidentalRelease', 'Prevent spill propagation. Collect immediately using dry absorbent materials.'),
('H410', 'EN', 'Disposal', 'Treat as highly ecotoxic waste. Recycle or destroy according to the applicable EWC code.');

-- ---------------------------------------------------------------------
-- [H411] Tóxico para os organismos aquáticos com efeitos duradouros
-- ---------------------------------------------------------------------
INSERT OR REPLACE INTO ClpPhraseTranslations (ClpPhraseId, LanguageCode, SectionType, TranslatedText) VALUES
('H411', 'PT', 'FirstAid', 'Se ingerido ou derramado em massa, consultar o médico especialista. Mostrar rótulo.'),
('H411', 'PT', 'AccidentalRelease', 'Evitar o escoamento direto para as valas pluviais ou furos de água. Conter com solo ou areia.'),
('H411', 'PT', 'Disposal', 'Obrigatório o envio de resíduos para eliminação através de canais licenciados de resíduos perigosos.'),
('H411', 'EN', 'FirstAid', 'If swallowed or spilled in large quantities, consult a medical specialist. Show label.'),
('H411', 'EN', 'AccidentalRelease', 'Prevent direct runoff into storm drains or water wells. Contain with soil or sand.'),
('H411', 'EN', 'Disposal', 'Mandatory waste disposal through certified dangerous waste collection streams.');
